1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code, +, and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab cycles the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::button::{Button, ButtonVariants};
12	use gpui_kit::component::input::{
13	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent, Rope,
14	};
15	use gpui_kit::component::tab::{Tab, TabBar};
16	use gpui_kit::component::{ActiveTheme, Disableable, Icon};
17	use gpui_kit::*;
18	use lsp_types::{CompletionContext, CompletionResponse};
19	
20	use crate::harness_mentions;
21	use crate::main_window::FocusChat;
22	use crate::piton_lsp::PitonSession;
23	use crate::piton_syntax;
24	use crate::project_directory::ProjectDirectory;
25	use crate::project_lsp::ProjectLsp;
26	
27	/// The input grows with its text up to this many rows, then scrolls.
28	const MAX_ROWS: usize = 12;
29	
30	/// Room the editor keeps free at the right of each line when soft wrapping.
31	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
32	
33	#[cfg(target_os = "macos")]
34	const SEND_SHORTCUT: &str = "⌘Enter";
35	#[cfg(not(target_os = "macos"))]
36	const SEND_SHORTCUT: &str = "Ctrl+Enter";
37	
38	/// The tabs the input sits in, in the order Tab cycles them.
39	const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];
40	
41	/// The side of the square + tab, a little under the height of the tabs.
42	const BOTH_TAB_SIZE: Pixels = px(26.);
43	
44	/// What a prompt is sent to work on: the selected tab.
45	#[derive(Clone, Copy, Debug, PartialEq)]
46	pub enum SendMode {
47	    Code,
48	    /// The code and the spec together.
49	    Both,
50	    Spec,
51	}
52	
53	impl SendMode {
54	    fn label(self) -> &'static str {
55	        match self {
56	            SendMode::Code => "Code",
57	            SendMode::Both => "Code and Spec",
58	            SendMode::Spec => "Spec",
59	        }
60	    }
61	
62	    fn tab(self) -> Tab {
63	        match self {
64	            // A half tab: a square + icon, sitting on the bottom of the bar
65	            // like the full tabs either side of it. The tab keeps its own
66	            // height, so a max height is what shortens it.
67	            SendMode::Both => Tab::new()
68	                .icon(Icon::new(IconName::Plus))
69	                .aria_label(self.label())
70	                .w(BOTH_TAB_SIZE)
71	                .max_h(BOTH_TAB_SIZE)
72	                .self_end(),
73	            _ => Tab::new().label(self.label()),
74	        }
75	    }
76	}
77	
78	/// Emitted with the input's text, and the mode it is sent in, when the user
79	/// sends it.
80	pub struct Submit {
81	    pub text: String,
82	    pub mode: SendMode,
83	}
84	
85	pub struct ChatInput {
86	    editor: Entity<EditorState>,
87	    /// The tab bar and its body, which Esc moves focus to: out of the input,
88	    /// but not onto nothing, where the window would hand it straight back.
89	    focus_handle: FocusHandle,
90	    /// Index into `TABS`.
91	    selected_tab: usize,
92	    lsp: Option<Arc<PitonSession>>,
93	    busy: bool,
94	    /// Width the editor's text was last laid out in, which decides where long
95	    /// lines soft wrap.
96	    text_width: Option<Pixels>,
97	    /// What the editor adds around its rows (padding and border) as last
98	    /// laid out, rounded to device pixels.
99	    chrome: Option<Pixels>,
100	    _subscriptions: Vec<Subscription>,
101	}
102	
103	impl EventEmitter<Submit> for ChatInput {}
104	
105	impl ChatInput {
106	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
107	        let editor = cx.new(|cx| {
108	            EditorState::new(window, cx)
109	                .language(piton_syntax::LANGUAGE_NAME)
110	                .line_number(false)
111	                .folding(false)
112	                .soft_wrap(true)
113	                // No empty rows below the last line: the input is sized to its
114	                // text, so any extra would be blank space, and it would leave
115	                // room for the editor to stay scrolled past the first line
116	                // after Enter grows the input.
117	                .scroll_beyond_last_line(Some(0))
118	                .placeholder(format!(
119	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
120	                ))
121	        });
122	        // Typing goes straight into the input, without clicking it first.
123	        editor.read(cx).focus_handle(cx).focus(window, cx);
124	
125	        let subscriptions = vec![
126	            cx.subscribe(&editor, |this, editor, event: &InputEvent, cx| {
127	                // An edit may be an accepted completion, whose import the
128	                // hidden anchor then takes on.
129	                if matches!(event, InputEvent::Change)
130	                    && let Some(lsp) = &this.lsp
131	                {
132	                    lsp.note_edit(&editor.read(cx).value());
133	                }
134	                // Re-render on every edit so the input can grow to fit its text.
135	                cx.notify();
136	            }),
137	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
138	        ];
139	
140	        let mut this = Self {
141	            editor,
142	            focus_handle: cx.focus_handle(),
143	            selected_tab: 0,
144	            lsp: None,
145	            busy: false,
146	            text_width: None,
147	            chrome: None,
148	            _subscriptions: subscriptions,
149	        };
150	        this.connect_lsp(cx);
151	        this
152	    }
153	
154	    /// The project's `piton lsp` session, once it is running.
155	    pub fn lsp(&self) -> Option<Arc<PitonSession>> {
156	        self.lsp.clone()
157	    }
158	
159	    /// Moves keyboard focus into the input.
160	    pub fn focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
161	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
162	    }
163	
164	    /// Inserts a harness mention at the cursor, after a space when the cursor
165	    /// follows other text, then moves focus into the input.
166	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
167	        self.editor.update(cx, |editor, cx| {
168	            let value = editor.value();
169	            let follows_text = value
170	                .get(..editor.cursor())
171	                .and_then(|before| before.chars().next_back())
172	                .is_some_and(|c| !c.is_whitespace());
173	            let text = if follows_text {
174	                format!(" {mention}")
175	            } else {
176	                mention.to_string()
177	            };
178	            editor.insert(text, window, cx);
179	        });
180	        self.focus(window, cx);
181	    }
182	
183	    #[cfg(test)]
184	    pub fn value(&self, cx: &App) -> SharedString {
185	        self.editor.read(cx).value()
186	    }
187	
188	    #[cfg(test)]
189	    pub fn is_focused(&self, window: &Window, cx: &App) -> bool {
190	        self.editor.read(cx).focus_handle(cx).is_focused(window)
191	    }
192	
193	    /// Marks the harness as working; sending then queues the prompt.
194	    pub fn set_busy(&mut self, busy: bool, cx: &mut Context<Self>) {
195	        self.busy = busy;
196	        cx.notify();
197	    }
198	
199	    /// Points completions at the project's `piton lsp`, once it is running.
200	    /// Harness mentions complete without it.
201	    fn connect_lsp(&mut self, cx: &mut Context<Self>) {
202	        let client = ProjectLsp::get(cx);
203	        let connected = self.lsp.as_ref().map(|lsp| Arc::as_ptr(lsp.client()));
204	        if client.as_ref().map(Arc::as_ptr) == connected {
205	            return;
206	        }
207	        self.lsp = client.map(|client| Arc::new(PitonSession::new(client)));
208	        self.set_completions(self.lsp.clone(), cx);
209	    }
210	
211	    fn set_completions(&mut self, lsp: Option<Arc<PitonSession>>, cx: &mut Context<Self>) {
212	        let completions = Rc::new(PromptCompletions { lsp });
213	        self.editor.update(cx, |editor, _| {
214	            editor.lsp_mut().completion_provider = Some(completions)
215	        });
216	    }
217	
218	    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
219	        let text = self.editor.read(cx).value().to_string();
220	        if text.is_empty() {
221	            return;
222	        }
223	        self.editor
224	            .update(cx, |editor, cx| editor.set_value("", window, cx));
225	        cx.emit(Submit {
226	            text,
227	            mode: TABS[self.selected_tab],
228	        });
229	    }
230	
231	    /// Esc closes an open completion menu, and otherwise takes focus out of
232	    /// the input.
233	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
234	        if self.editor.read(cx).completion_menu_state().open {
235	            self.editor.update(cx, |editor, cx| {
236	                editor.route_overlay_action(Box::new(Escape), window, cx)
237	            });
238	        } else {
239	            self.focus_handle.focus(window, cx);
240	        }
241	    }
242	
243	    /// The rows `text` takes in the editor: one per line, plus one for every
244	    /// soft wrap, wrapped the way the editor wraps it.
245	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
246	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
247	            return text.split('\n').count();
248	        };
249	        let theme = cx.theme();
250	        let mut wrapper = window
251	            .text_system()
252	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
253	        text.split('\n')
254	            .map(|line| {
255	                1 + wrapper
256	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
257	                    .count()
258	            })
259	            .sum()
260	    }
261	}
262	
263	impl Render for ChatInput {
264	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
265	        let text = self.editor.read(cx).value();
266	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
267	        // Fit the text with the editor's own metrics: its laid-out line height
268	        // plus the padding and border around its rows. Until the editor has
269	        // painted, the border is estimated at a device pixel or more per side.
270	        let line_height = self
271	            .editor
272	            .read(cx)
273	            .line_height()
274	            .unwrap_or_else(|| window.line_height());
275	        let chrome = self.chrome.unwrap_or_else(|| {
276	            gpui_kit::component::Size::Medium.input_py() * 2.
277	                + ceil_to_device_pixel(px(1.), window) * 2.
278	        });
279	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
280	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
281	        let empty = text.is_empty();
282	
283	        // Once the editor has painted, check how it was laid out: the width
284	        // its text wrapped in (a resized window wraps long lines differently)
285	        // and the padding and border around its rows. When either changed,
