    for expected in [1, 2, 0, 1] {
        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
            .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            let input = chat_input.read(cx);
            assert_eq!(input.selected_tab, expected);
            assert_eq!(input.value(cx).as_ref(), "hi");
            assert!(input.is_focused(window, cx), "the input lost focus on Tab");
        })
        .unwrap();
    }
}

/// The + tab sits between Code and Spec: a square a little shorter than
/// the tabs either side of it, level with their bottoms.
#[gpui_kit::test]
async fn plus_tab_is_a_square_half_tab(cx: &mut TestAppContext) {
    cx.update(|cx| {
        gpui_kit::init(cx);
        piton_syntax::init();
        ProjectDirectory::init(cx);
    });
    let window = cx.add_window(|window, cx| {
        let input = cx.new(|cx| ChatInput::new(window, cx));
        Root::new(input, window, cx)
    });
    let handle = window.into();
    cx.wait_for(handle, TIMEOUT, |window, _| {
        window.try_find("prompt-editor").is_some()
    })
    .await;

    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        let tabs = window.within("chat-tabs");
        let code = tabs.find(0usize).bounds();
        let plus = tabs.find(1usize).bounds();
        let spec = tabs.find(2usize).bounds();
        assert_eq!(
            plus.size.width, plus.size.height,
            "+ tab {plus:?} is not square"
        );
        assert!(
            plus.size.height < code.size.height,
            "+ tab {plus:?} is not shorter than Code {code:?}"
        );
        assert!(
            code.right() <= plus.left() && plus.right() <= spec.left(),
            "+ tab {plus:?} is not between Code {code:?} and Spec {spec:?}"
        );
        assert_eq!(
            plus.bottom(),
            code.bottom(),
            "+ tab {plus:?} is not level with Code {code:?}"
        );
    })
    .unwrap();
}

