568	    /// Set if the tab bar has a prefix.
569	    pub(crate) fn tab_bar_prefix(mut self, tab_bar_prefix: bool) -> Self {
570	        self.tab_bar_prefix = Some(tab_bar_prefix);
571	        self
572	    }
