        })
        .await;

        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            let tabs = window.within("chat-tabs");
            let code = tabs.find(0usize).bounds();
            let plus = tabs.find(1usize).bounds();
            let spec = tabs.find(2usize).bounds();
            assert_eq!(
                plus.size.width, plus.size.height,
