    /// The chat input along the bottom of the window, where prompt mode puts it.
    struct AtBottom(Entity<ChatInput>);

    impl Render for AtBottom {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div()
                .size_full()
                .flex()
                .flex_col()
                .justify_end()
